     9→import lombok.extern.slf4j.Slf4j;
    10→import org.springframework.stereotype.Controller;
    11→import org.springframework.ui.Model;
    12→import org.springframework.validation.BindingResult;
    13→import org.springframework.web.bind.annotation.GetMapping;
    14→import org.springframework.web.bind.annotation.PostMapping;
    15→
    16→import javax.validation.Valid;
    17→import java.io.FileNotFoundException;
    18→import java.io.FileOutputStream;
    19→
    20→@Controller
    21→@Slf4j
    22→public class PdfController {
    23→
    24→    private PdfService pdfService;
    25→
    26→    public PdfController(PdfService pdfService) {
    27→        this.pdfService = pdfService;
    28→    }
    29→
    30→    private void generateSamplePdf(String fileName, String text) throws FileNotFoundException, DocumentException {
    31→        if (!fileName.endsWith(".pdf")) {
    32→            fileName += ".pdf";
    33→        }
    34→        Document document = new Document();
    35→        PdfWriter.getInstance(document, new FileOutputStream(fileName));
    36→        document.open();
    37→        Paragraph paragraph = new Paragraph(text);
    38→        document.add(paragraph);
    39→        document.close();
    40→    }
    41→
    42→    @GetMapping("/pdf-generator")
    43→    public String pdfGenerator(Model model) {
    44→        model.addAttribute("pdf", new Pdf());
    45→        return "pdf/generator";
    46→    }
    47→
    48→    @PostMapping("/pdf-generator")
    49→    public String generatePdf(@Valid Pdf pdf, BindingResult bindingResult) {
    50→        if (bindingResult.hasErrors()) {
    51→            return "redirect:/pdf-generator";
    52→        } else {
    53→            try {
    54→                generateSamplePdf(pdf.getName(), pdf.getContent());
    55→                pdfService.savePdf(pdf);
    56→            } catch (FileNotFoundException e) {
    57→                log.info("File Not Found");
    58→            } catch (DocumentException e) {
    59→                log.info("Document");
    60→            }
    61→            return "pdf/success";
    62→        }
